import{_ as t,H as _,f as a,i as p}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"迭代｜全新交付专栏全部音频","description":"","frontmatter":{},"headers":[],"relativePath":"左耳听风/迭代｜全新交付专栏全部音频.md","filePath":"左耳听风/迭代｜全新交付专栏全部音频.md","lastUpdated":1779819815000}'),r={name:"左耳听风/迭代｜全新交付专栏全部音频.md"};function o(i,e,l,s,n,d){return _(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="迭代-全新交付专栏全部音频" tabindex="-1">迭代｜全新交付专栏全部音频 <a class="header-anchor" href="#迭代-全新交付专栏全部音频" aria-label="Permalink to &quot;迭代｜全新交付专栏全部音频&quot;">​</a></h1><p>你好，我是极客时间专栏的编辑杨静。</p><p>2017年10月10日，《左耳听风》专栏上线了，它是极客时间平台上最早交付的几门课程之一。在这门课中，资深技术专家、骨灰级程序员陈皓对他多年来的经验和思考进行了系统性的梳理、总结。到2018年10月专栏结课，我们在一年内更新了110多讲内容。</p><p>截止到今天，也就是 2022 年 4 月 1 日，距离《左耳听风》这个专栏结课已经过去差不多三年半的时间了。一直到现在，它依然是极客时间上体量最大、学习人数最多的几门课程之一。这门课的文章有 60,691 次收藏，169,976 处划线，16,878 条笔记。这些都是我们一起学习的印记，是我们持续努力、不断精进的点滴证明。</p><p>感谢每一位同学在课程评论区中的积极留言。你不仅分享了自己的学习收获、心得与经验，提出了自己的疑惑和问题，还反馈了课程中的不足，帮助我们一起将这门课打磨得更加完美。真心感谢你的每一次批评指正。</p><p>这些反馈中，提及比较多的是音频问题。基于此，我们决定对专栏的音频内容进行全面替换（除结束语），修正过去存在的错误，并且进一步优化讲述感。同时，在音频迭代的过程中，我们也重新检查了一遍文稿内容，纠正了一些错别字及语句不顺的问题。这样，后面新加入的同学可以获得更好的学习体验，已经学完的同学也可以在复习的时候有不一样的感受。</p><p>这次音频迭代涉及课程里的 117 讲内容，我们会分两次全部替换完。音频替换计划如下：</p><ul><li>4 月 1 日，替换开篇词、01 讲～60讲；</li><li>7 月 1 日前，替换 61 讲～115 讲，以及加餐。</li></ul><p>希望这次全新迭代的音频，能给你更好的学习体验。如果你还有其他问题，也欢迎继续给我们提供反馈。</p><p>正如陈皓老师在这门课结束语中所说的那样，“学习是没有捷径的，是逆人性的，你需要长期地付出时间和精力”。这个专栏现在有近120讲内容，体量非常大，需要你投入大量的时间和精力才能学完、理解透彻，并在实践中应用。每一位持之以恒学习这门课的同学，都值得被敬佩。</p><p>学习没有捷径，而在这个充满不确定的世界，持续学习才是唯一确定的“捷径”。希望这门课的每一位同学都能像陈皓老师所期待的那样，不断挑战自己，“洞悉技术的本质，享受科技的乐趣”！</p>',11)])])}const m=t(r,[["render",o]]);export{f as __pageData,m as default};
